#!/usr/bin/env python3
"""Clanker QA driver.

Posts tasks to Clanker as a tester account, waits for each turn to settle,
collects transcripts and diagnostic evidence, and keeps the loop ledger in
.local/clanker-qa/. Every command prints JSON. Tokens are never printed or
passed as command arguments.

Run with the lab venv, which provides slack_sdk, python-dotenv and PyYAML:

  /Users/tanishqpalandurkar/Projects/yyot/.local/hermes-lab/venv/bin/python \
      ~/.codex/skills/clanker-qa/scripts/clanker_qa.py <command> --help
"""
from __future__ import annotations

import argparse
import collections
import contextlib
import datetime as dt
import difflib
import hashlib
import html
import json
import os
import re
import shutil
import signal
import sqlite3
import subprocess
import sys
import tempfile
import time
import urllib.request
from pathlib import Path

PROJECT = Path('/Users/tanishqpalandurkar/Projects/yyot')
SKILL_FILE = Path(__file__).resolve().parents[1] / 'SKILL.md'
WAKE = 'AGENT_LOOP_WAKE_clanker-qa'

DEFAULTS = {
    'project': str(PROJECT),
    'lab_home': str(PROJECT / '.local/hermes-lab/home'),
    'state_dir': str(PROJECT / '.local/clanker-qa'),
    'benchmark': str(PROJECT / 'docs/CLANKER_BENCHMARK.md'),
    'kernel_cli': '/Users/tanishqpalandurkar/.npm-global/bin/kernel',
    'kernel_project': None,
    'team_id': 'T0C6J1XCDE0',
    'domain': 'clanker-global.slack.com',
    'bot_user': 'U0C5Z1ZQHQX',
    'bot_app': 'A0C78PBUKQQ',
    'operator_user': 'U0C684PHZ5H',
    'test_channel': 'C0C6J277ZNG',
    'testers': {
        'tanishq': {'user': 'U0C688SF7DZ', 'token_key': 'CLANKER_QA_TANISHQ_USER_TOKEN'},
        'yyovil': {'user': 'U0C6M6DMWAW', 'token_key': 'CLANKER_QA_YYOVIL_USER_TOKEN'},
    },
    'budget': {'max_runs_per_day': 24, 'min_gap_seconds': 120, 'max_messages_per_run': 8},
    'wait': {'poll_seconds': 12, 'quiet_seconds': 45, 'first_reply_seconds': 180,
             'timeout_seconds': 1800, 'stall_seconds': 900, 'heartbeat_seconds': 1500},
    'restart': {'idle_polls': 2, 'idle_poll_seconds': 15, 'recent_activity_seconds': 90,
                'max_wait_seconds': 1800, 'health_timeout_seconds': 180},
}

REQUIRED_SCOPES = ('chat:write', 'channels:history', 'im:history', 'im:read')
RECOMMENDED_SCOPES = ('channels:read', 'groups:history', 'groups:read', 'files:read', 'reactions:read')
VARIANTS = ('verbatim', 'paraphrase', 'casual', 'split', 'mid_task_followup', 'edit_after_send',
            'interrupt', 'new_thread_continuation', 'surface_swap', 'cross_user')
VERDICTS = ('pass', 'fail', 'blocked', 'inconclusive', 'infra')
SEVERITIES = ('S1', 'S2', 'S3', 'S4')
FINDING_STATUSES = ('diagnosing', 'fixed_pending_restart', 'deployed', 'verified', 'upstream',
                    'wontfix', 'needs_human')
OPEN_STATUSES = ('diagnosing', 'fixed_pending_restart', 'deployed', 'needs_human')
PAYMENT_TOOLS = ('clanker_request_payment', 'clanker_payment_fill', 'clanker_payment_submit')
IGNORED_SUBTYPES = {'channel_join', 'channel_leave', 'channel_topic', 'channel_purpose', 'pinned_item'}
BLOCKED_TOP_LEVEL = {'.local', '.git', '.entire', '.playwright-cli', 'output', 'videos'}
PROTECTED_FILES = {'docs/CLANKER_BENCHMARK.md'}


class QAError(Exception):
    """An expected failure, reported as JSON with an actionable message."""

    def __init__(self, message, **detail):
        super().__init__(message)
        self.detail = detail


# ---------------------------------------------------------------- configuration

class Config:
    def __init__(self, data):
        self.data = data
        self.project = Path(data['project'])
        self.lab_home = Path(data['lab_home'])
        self.state_dir = Path(data['state_dir'])
        self.benchmark = Path(data['benchmark'])

    def __getattr__(self, name):
        try:
            return self.__dict__['data'][name]
        except KeyError:
            raise AttributeError(name) from None

    @property
    def lab_python(self):
        return self.project / '.local/hermes-lab/venv/bin/python'

    def tester_names(self):
        return sorted(self.testers)

    def tester_by_user(self):
        return {spec['user']: name for name, spec in self.testers.items()}


def deep_merge(base, override):
    merged = dict(base)
    for key, value in (override or {}).items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            merged[key] = deep_merge(base[key], value)
        else:
            merged[key] = value
    return merged


def load_config():
    state_dir = Path(os.environ.get('CLANKER_QA_STATE_DIR') or DEFAULTS['state_dir'])
    data = deep_merge(DEFAULTS, read_json(state_dir / 'config.json', {}))
    data['state_dir'] = str(state_dir)
    return Config(data)


# ---------------------------------------------------------------- files and time

def out(value):
    print(json.dumps(value, indent=1, ensure_ascii=False, default=str), flush=True)


def read_json(path, default):
    try:
        return json.loads(Path(path).read_text(encoding='utf-8'))
    except FileNotFoundError:
        return default


def write_file(path, data, mode=0o600):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(dir=path.parent, prefix='.' + path.name + '.')
    try:
        with os.fdopen(fd, 'wb') as handle:
            handle.write(data.encode('utf-8') if isinstance(data, str) else data)
        os.chmod(temporary, mode)
        os.replace(temporary, path)
    except BaseException:
        with contextlib.suppress(FileNotFoundError):
            os.unlink(temporary)
        raise


def write_json(path, value):
    write_file(path, json.dumps(value, indent=1, ensure_ascii=False, default=str) + '\n')


def append_jsonl(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, 'a', encoding='utf-8') as handle:
        handle.write(json.dumps(value, ensure_ascii=False, default=str) + '\n')
    os.chmod(path, 0o600)


def read_jsonl(path):
    try:
        lines = Path(path).read_text(encoding='utf-8').splitlines()
    except FileNotFoundError:
        return []
    return [json.loads(line) for line in lines if line.strip()]


def env_value(path, key):
    path = Path(path)
    if not path.exists():
        return ''
    from dotenv import dotenv_values
    return (dotenv_values(path, interpolate=False).get(key) or '').strip()


def sha256_file(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def iso_utc(epoch):
    return dt.datetime.fromtimestamp(epoch, dt.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')


def local_clock(epoch):
    return dt.datetime.fromtimestamp(epoch).strftime('%H:%M:%S')


def local_day(epoch):
    return dt.datetime.fromtimestamp(epoch).date().isoformat()


# ---------------------------------------------------------------- redaction

REDACTIONS = (
    (re.compile(r'xox[abeoprs]-[A-Za-z0-9-]+'), '[slack-token]'),
    (re.compile(r'\b(?:sk|rk|pk)-[A-Za-z0-9_-]{16,}'), '[api-key]'),
    (re.compile(r'(?i)\bbearer\s+[A-Za-z0-9._~+/=-]{12,}'), 'Bearer [redacted]'),
    (re.compile(r'eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{6,}'), '[jwt]'),
    (re.compile(r'wss?://[^\s"\'<>)]+'), '[websocket-url]'),
    (re.compile(r'(?i)([?&#](?:token|jwt|key|sig|signature|secret|code|auth|session|x-amz-[a-z-]+)=)'
                r'[^&\s"\'<>]+'), r'\1[redacted]'),
    (re.compile(r'(?<![\d.])(?:\d[ -]?){13,19}(?![\d.])'), '[long-number]'),
)


def redact(text):
    text = str(text)
    for pattern, replacement in REDACTIONS:
        text = pattern.sub(replacement, text)
    return text


def clip(text, limit):
    text = str(text or '')
    return text if len(text) <= limit else text[:limit] + f' … [{len(text) - limit} more chars]'


# ---------------------------------------------------------------- benchmark

STOPWORDS = {'a', 'an', 'and', 'are', 'can', 'do', 'for', 'from', 'get', 'i', 'in', 'into', 'is', 'it',
             'me', 'my', 'of', 'on', 'or', 'our', 'please', 'the', 'to', 'us', 'using', 'we', 'what',
             'with', 'you', 'your'}
CHANNEL_HINTS = ('help us', 'company', 'the team', 'everyone', 'planning thread', 'we were planning')
GATE_HINTS = ('sign me into', 'sign in', 'log in', 'login', 'two-factor', 'authenticator',
              'verification code', 'otp')


def clean_cell(cell):
    cell = html.unescape(re.sub(r'<br\s*/?>', '\n', cell, flags=re.I))
    return '\n'.join(' '.join(line.split()) for line in cell.splitlines()).strip()


def scenario_id(text):
    normalized = ' '.join(text.lower().split())
    words = [word for word in re.findall(r'[a-z0-9]+', normalized) if word not in STOPWORDS]
    slug = '-'.join(words[:3]) or 'scenario'
    return f'{slug}-{hashlib.sha1(normalized.encode()).hexdigest()[:4]}'


def parse_benchmark(text):
    rows = []
    for line in text.splitlines():
        line = line.strip()
        if not (line.startswith('|') and line.endswith('|')):
            continue
        cells = [cell.strip() for cell in line[1:-1].split('|')]
        if len(cells) < 2 or re.fullmatch(r'[-:\s]*', cells[0]) or cells[0].lower() == 'initial prompt':
            continue
        initial = clean_cell(cells[0])
        followups = [clean_cell(part) for part in re.split(r'(?:<br\s*/?>\s*){2,}', cells[1], flags=re.I)]
        everything = (initial + ' ' + cells[1]).lower()
        rows.append({
            'id': scenario_id(initial),
            'index': len(rows) + 1,
            'initial': initial,
            'followups': [followup for followup in followups if followup],
            'surface_hint': 'channel' if any(hint in initial.lower() for hint in CHANNEL_HINTS) else 'dm',
            'gate_likely': any(hint in everything for hint in GATE_HINTS),
        })
    return rows


def load_rows(cfg):
    try:
        return parse_benchmark(cfg.benchmark.read_text(encoding='utf-8'))
    except FileNotFoundError:
        raise QAError('The benchmark file is missing', path=str(cfg.benchmark)) from None


def scenario_for(cfg, scenario, text):
    if scenario == 'adhoc':
        if not text:
            raise QAError('An adhoc scenario needs --text')
        return {'id': 'adhoc-' + hashlib.sha1(text.encode()).hexdigest()[:6], 'initial': text, 'followups': []}
    rows = {row['id']: row for row in load_rows(cfg)}
    if scenario not in rows:
        raise QAError('Unknown scenario', scenario=scenario, available=sorted(rows))
    return rows[scenario]


# ---------------------------------------------------------------- slack

def slack_client(token):
    from slack_sdk import WebClient
    from slack_sdk.http_retry.builtin_handlers import RateLimitErrorRetryHandler
    client = WebClient(token=token, timeout=30)
    client.retry_handlers.append(RateLimitErrorRetryHandler(max_retry_count=4))
    return client


def call(client, method, **params):
    from slack_sdk.errors import SlackApiError
    try:
        return getattr(client, method)(**params)
    except SlackApiError as error:
        data = getattr(error.response, 'data', None) or {}
        raise QAError(f"Slack {method} failed: {data.get('error', 'unknown_error')}",
                      slack_error=data.get('error'), needed=data.get('needed')) from None


def header(response, name):
    for key, value in (getattr(response, 'headers', None) or {}).items():
        if key.lower() == name:
            return value[0] if isinstance(value, list) else value
    return ''


_TESTERS = {}


def tester(cfg, name):
    """Return the verified Slack client for a tester. Identity is checked once per process."""
    if name in _TESTERS:
        return _TESTERS[name]
    spec = cfg.testers.get(name)
    if not spec:
        raise QAError(f'Unknown tester {name!r}', testers=cfg.tester_names())
    token = env_value(cfg.state_dir / '.env', spec['token_key'])
    if not token:
        raise QAError(f'No Slack user token for {name}',
                      fix=f"Add {spec['token_key']}=xoxp-... to {cfg.state_dir / '.env'} (mode 600).")
    if not token.startswith('xoxp-'):
        raise QAError(f"{spec['token_key']} must be a Slack user token (xoxp-)")
    client = slack_client(token)
    identity = call(client, 'auth_test')
    if (identity.get('team_id') != cfg.team_id or identity.get('user_id') != spec['user']
            or identity.get('bot_id')):
        raise QAError(f"The token for {name} does not belong to {spec['user']} in {cfg.team_id}",
                      team=identity.get('team_id'), user=identity.get('user_id'))
    scopes = {scope.strip() for scope in header(identity, 'x-oauth-scopes').split(',') if scope.strip()}
    _TESTERS[name] = {'client': client, 'token': token, 'scopes': scopes, 'user': spec['user']}
    return _TESTERS[name]


def tester_dm(cfg, name):
    user = cfg.testers[name]['user']
    membership = read_json(cfg.lab_home / 'slack_membership.json', {})
    dm = ((membership.get('members') or {}).get(user) or {}).get('dm_id')
    if not dm:
        raise QAError(f'No Clanker DM is recorded for {name} in slack_membership.json')
    return dm


def channel_label(cfg, channel):
    if channel == cfg.test_channel:
        return '#clanker-test'
    for name in cfg.tester_names():
        with contextlib.suppress(QAError):
            if tester_dm(cfg, name) == channel:
                return f'DM {name}'
    return channel


def permalink(cfg, channel, ts, thread=None):
    link = f"https://{cfg.domain}/archives/{channel}/p{ts.replace('.', '')}"
    if thread and thread != ts:
        link += f'?thread_ts={thread}&cid={channel}'
    return link


MASS_MENTION = re.compile(r'<!(?:channel|here|everyone)\b|(?<![\w<])@(?:channel|here|everyone)\b', re.I)
SECRETISH = re.compile(r'xox[abeoprs]-|(?<![\d.])(?:\d[ -]?){13,19}(?![\d.])')


def check_text(cfg, text):
    if not text.strip():
        raise QAError('Refusing to post an empty message')
    if MASS_MENTION.search(text):
        raise QAError('Refusing to post a channel-wide mention')
    allowed = {cfg.bot_user, *cfg.tester_by_user()}
    for user in re.findall(r'<@([UW][A-Z0-9]+)', text):
        if user not in allowed:
            raise QAError('Testers may mention only Clanker or each other', user=user)
    if SECRETISH.search(text):
        raise QAError('Refusing to post something that looks like a token or card number')


def paged(client, method, **params):
    items, cursor, seen = [], None, set()
    while True:
        page = call(client, method, limit=200, **params, **({'cursor': cursor} if cursor else {}))
        items.extend(page.get('messages') or [])
        cursor = (page.get('response_metadata') or {}).get('next_cursor')
        if not cursor:
            return items
        if cursor in seen:
            raise QAError(f'Slack {method} repeated a pagination cursor')
        seen.add(cursor)


def find_recent_post(cfg, actor, channel, thread, text, since):
    """Find a post whose response was lost, so a retry never double-posts."""
    client = tester(cfg, actor)['client']
    try:
        if thread:
            items = paged(client, 'conversations_replies', channel=channel, ts=thread)
        else:
            items = paged(client, 'conversations_history', channel=channel,
                          oldest=f'{since - 5:.6f}', inclusive=True)
    except QAError:
        return None
    user = cfg.testers[actor]['user']
    for message in items:
        if (message.get('user') == user and float(message['ts']) >= since - 5
                and html.unescape(message.get('text') or '') == text):
            return message['ts']
    return None


def post_message(cfg, actor, channel, text, thread=None):
    allowed = {tester_dm(cfg, actor), cfg.test_channel}
    if channel not in allowed:
        raise QAError('A tester may post only in their own Clanker DM or #clanker-test', channel=channel)
    check_text(cfg, text)
    client = tester(cfg, actor)['client']
    params = {'channel': channel, 'text': text, 'unfurl_links': False, 'unfurl_media': False}
    if thread:
        params['thread_ts'] = thread
    sent_at = time.time()
    try:
        return call(client, 'chat_postMessage', **params)['ts']
    except QAError:
        raise
    except Exception as error:
        found = find_recent_post(cfg, actor, channel, thread, text, sent_at)
        if found:
            return found
        raise QAError(f'Posting failed ({type(error).__name__}); it did not appear in Slack') from None


# ---------------------------------------------------------------- conversation

def actor_of(cfg, message):
    user = message.get('user')
    if user == cfg.bot_user or (not user and (message.get('bot_profile') or {}).get('app_id') == cfg.bot_app):
        return 'clanker'
    return cfg.tester_by_user().get(user, 'other')


def render_text(cfg, text):
    names = {cfg.bot_user: 'clanker', cfg.operator_user: 'operator', **cfg.tester_by_user()}
    text = re.sub(r'<@([UW][A-Z0-9]+)(?:\|[^>]*)?>', lambda m: '@' + names.get(m.group(1), m.group(1)), text or '')
    text = re.sub(r'<#(C[A-Z0-9]+)(?:\|([^>]*))?>', lambda m: '#' + (m.group(2) or m.group(1)), text)
    text = re.sub(r'<(https?://[^|>]+)\|([^>]+)>', r'\2 (\1)', text)
    text = re.sub(r'<(https?://[^>]+)>', r'\1', text)
    return html.unescape(text)


def buttons_of(blocks):
    labels = []
    for block in blocks or []:
        elements = list(block.get('elements') or []) if block.get('type') == 'actions' else []
        if block.get('accessory'):
            elements.append(block['accessory'])
        for element in elements:
            if element.get('type') == 'button':
                labels.append(((element.get('text') or {}).get('text') or element.get('action_id') or '').strip())
    return labels


def normalize(cfg, message, channel, ours):
    files = [{'id': item.get('id'), 'name': item.get('name'), 'mimetype': item.get('mimetype'),
              'size': item.get('size'), 'url': item.get('url_private_download') or item.get('url_private')}
             for item in message.get('files') or []]
    return {
        'channel': channel, 'ts': message['ts'], 'thread': message.get('thread_ts') or message['ts'],
        'user': message.get('user'), 'actor': actor_of(cfg, message), 'ours': message['ts'] in ours,
        'text': render_text(cfg, message.get('text') or ''), 'buttons': buttons_of(message.get('blocks')),
        'files': files, 'edited_ts': (message.get('edited') or {}).get('ts'), 'subtype': message.get('subtype'),
        'reactions': [{'name': r.get('name'), 'users': r.get('users') or []} for r in message.get('reactions') or []],
    }


def activity_time(message):
    return max(float(message['ts']), float(message.get('edited_ts') or 0))


def posts(run):
    return [message for message in run['messages'] if message['kind'] != 'edit']


def last_tester_activity(run):
    return max(float(m['ts']) if m['kind'] != 'edit' else m['at'] - 2 for m in run['messages'])


def reader_name(cfg, run, channel):
    for name in run['testers']:
        if tester_dm(cfg, name) == channel:
            return name
    return run['actor']


def collect(cfg, run):
    """Return run messages (root threads plus Clanker-started conversations) and retrieval gaps."""
    ours = {message['ts'] for message in posts(run)}
    roots = {(root['channel'], root['ts']) for root in run['roots']}
    found, notes = {}, []

    def add(message, channel, related):
        if message.get('subtype') not in IGNORED_SUBTYPES:
            item = normalize(cfg, message, channel, ours)
            item['related'] = related
            found[(channel, message['ts'])] = item

    for channel, root in sorted(roots):
        client = tester(cfg, reader_name(cfg, run, channel))['client']
        try:
            for message in paged(client, 'conversations_replies', channel=channel, ts=root):
                add(message, channel, 'run')
        except QAError as error:
            notes.append(f'{channel_label(cfg, channel)} thread {root}: {error}')
    for channel in run['watch']:
        client = tester(cfg, reader_name(cfg, run, channel))['client']
        try:
            top = paged(client, 'conversations_history', channel=channel,
                        oldest=f"{run['started_at'] - 5:.6f}", inclusive=True)
        except QAError as error:
            notes.append(f'{channel_label(cfg, channel)} history: {error}')
            continue
        for message in top:
            if (channel, message['ts']) in roots:
                continue
            by_clanker = actor_of(cfg, message) == 'clanker'
            if not by_clanker and message['ts'] not in ours:
                continue
            add(message, channel, 'clanker-initiated' if by_clanker else 'run')
            if message.get('reply_count'):
                try:
                    for reply in paged(client, 'conversations_replies', channel=channel, ts=message['ts']):
                        add(reply, channel, 'clanker-initiated')
                except QAError as error:
                    notes.append(f'{channel_label(cfg, channel)} thread {message["ts"]}: {error}')
    return sorted(found.values(), key=lambda item: float(item['ts'])), notes


GATE_PATTERNS = {
    'sign_in_link': re.compile(r'(?i)\b(sign[ -]?in|log[ -]?in|access)\b[^\n]{0,80}\b(link|page|here)\b'),
    'verification_code': re.compile(r'(?i)\b(otp|one[- ]time|verification code|2fa|authenticator)\b'),
    'approval': re.compile(r'(?i)\b(approve|approval|authori[sz]e|confirm (?:the )?payment)\b'),
    'captcha': re.compile(r'(?i)\b(captcha|are you a robot|human verification)\b'),
}


def gate_hints(messages):
    hints = {name for message in messages for name, pattern in GATE_PATTERNS.items()
             if pattern.search(message['text'])}
    if any(message['buttons'] for message in messages):
        hints.add('button')
    return sorted(hints)


def download_files(cfg, run, messages, folder, notes):
    saved = {}
    for message in messages:
        if message['actor'] != 'clanker':
            continue
        for item in message['files']:
            mimetype = str(item.get('mimetype') or '')
            if not item.get('url') or not item.get('id') or (item.get('size') or 0) > 15_000_000:
                continue
            if not mimetype.startswith(('image/', 'application/pdf', 'text/')):
                continue
            name = re.sub(r'[^A-Za-z0-9._-]', '_', item.get('name') or 'file')[:80]
            path = folder / f"{item['id']}-{name}"
            if not path.exists():
                token = tester(cfg, reader_name(cfg, run, message['channel']))['token']
                request = urllib.request.Request(item['url'], headers={'Authorization': 'Bearer ' + token})
                try:
                    with urllib.request.urlopen(request, timeout=30) as response:
                        data = response.read(15_000_001)
                except OSError as error:
                    notes.append(f"file {item['id']}: {type(error).__name__}")
                    continue
                if data[:200].lstrip().lower().startswith((b'<!doctype html', b'<html')):
                    notes.append(f"file {item['id']}: Slack returned a login page (files:read scope missing?)")
                    continue
                write_file(path, data)
            saved[item['id']] = str(path)
    return saved


def render_transcript(cfg, run, messages, files, notes, settles):
    start = run['started_at']
    root = run['roots'][0]
    lines = [f"# Run {run['id']}", '',
             f"- Scenario `{run['scenario']}`, variant `{run['variant']}`, surface `{run['surface']}`",
             f"- Testers: {', '.join(run['testers'])} (primary {run['actor']})",
             f"- Started {local_clock(start)} local ({iso_utc(start)}): {permalink(cfg, root['channel'], root['ts'])}"]
    if run.get('verify'):
        lines.append(f"- Verifies finding `{run['verify']}`")
    if run.get('gate'):
        lines.append(f"- Human gate pending: {run['gate']['what']}")
    lines += ['', '## Benchmark script', '', f"Initial: {run['scenario_text']}"]
    for index, followup in enumerate(run.get('followups') or []):
        sent = 'sent' if index in run.get('sent_followups', []) else 'not sent'
        lines.append(f'{index}. [{sent}] ' + followup.replace('\n', ' '))
    edits = collections.defaultdict(list)
    for message in run['messages']:
        if message['kind'] == 'edit':
            edits[message['ts']].append(message)
    groups = collections.OrderedDict()
    for message in messages:
        groups.setdefault((message['related'] != 'run', message['channel'], message['thread']), []).append(message)
    lines += ['', '## Conversation']
    for (other, channel, thread), items in sorted(groups.items(), key=lambda kv: (kv[0][0], float(kv[0][2]))):
        lines += ['', f"### {channel_label(cfg, channel)}, thread {thread} ({'Clanker-initiated' if other else 'run'})",
                  permalink(cfg, channel, thread)]
        for message in items:
            who = message['actor']
            if message['ours']:
                who += ' (loop)'
            elif message['actor'] in cfg.testers:
                who += ' (typed manually)'
            offset = int(float(message['ts']) - start)
            text = message['text'].replace('\n', '\n    ')
            lines.append(f"- [+{offset}s {local_clock(float(message['ts']))}] **{who}**: {text}")
            for edit in edits.get(message['ts'], []):
                lines.append(f"    - edited by loop at +{int(edit['at'] - start)}s")
            if message['edited_ts'] and not edits.get(message['ts']):
                lines.append(f"    - edited at +{int(float(message['edited_ts']) - start)}s")
            if message['buttons']:
                lines.append('    - buttons: ' + ' · '.join(message['buttons']))
            for item in message['files']:
                local = files.get(item['id'])
                lines.append(f"    - file: {item.get('name')} ({item.get('mimetype')})" + (f' saved at {local}' if local else ''))
            for reaction in message['reactions']:
                who_reacted = ', '.join(cfg.tester_by_user().get(u, 'clanker' if u == cfg.bot_user else u)
                                        for u in reaction['users'])
                lines.append(f"    - reaction :{reaction['name']}: by {who_reacted}")
    if settles:
        lines += ['', '## Wait events', '']
        lines += [f"- +{int(s['at'] - start)}s {s['event']}: {s['reason']}" for s in settles]
    if notes:
        lines += ['', '## Retrieval gaps', ''] + [f'- {note}' for note in notes]
    return '\n'.join(lines) + '\n'


# ---------------------------------------------------------------- local hermes state

def session_dbs(cfg):
    paths = [cfg.lab_home / 'state.db', *sorted(cfg.lab_home.glob('profiles/*/state.db'))]
    return [path for path in paths if path.exists()]


@contextlib.contextmanager
def readonly(path):
    db = sqlite3.connect(f'file:{path}?mode=ro', uri=True, timeout=3)
    db.row_factory = sqlite3.Row
    try:
        yield db
    finally:
        db.close()


def find_sessions(cfg, run):
    threads = {(root['channel'], root['ts']) for root in run['roots']}
    channels = sorted({channel for channel, _ in threads} | set(run['watch']))
    testers = {cfg.testers[name]['user'] for name in run['testers']}
    since = run['started_at'] - 60
    sessions, errors = [], []
    marks = ','.join('?' * len(channels))
    for path in session_dbs(cfg):
        profile = 'default' if path.parent == cfg.lab_home else path.parent.name
        try:
            with readonly(path) as db:
                rows = db.execute(
                    'SELECT id, chat_id, thread_id, user_id, session_key, profile_name, started_at '
                    f"FROM sessions WHERE source='slack' AND chat_id IN ({marks})", channels).fetchall()
        except sqlite3.Error as error:
            errors.append(f'{profile} state.db: {error}')
            continue
        for row in rows:
            thread_match = (row['chat_id'], row['thread_id']) in threads
            time_match = (row['started_at'] or 0) >= since and (row['user_id'] in testers or not row['user_id'])
            if thread_match or time_match:
                sessions.append({'db': str(path), 'profile': row['profile_name'] or profile, 'id': row['id'],
                                 'key': row['session_key'], 'chat': row['chat_id'], 'thread': row['thread_id'],
                                 'user': row['user_id'], 'started_at': row['started_at'],
                                 'match': 'thread' if thread_match else 'time'})
    return sessions, errors


def admitted_posts(cfg, timestamps):
    """Map each Slack ts to whether any Hermes session recorded it; None when unreadable."""
    result = {ts: None for ts in timestamps}
    readable = False
    for path in session_dbs(cfg):
        try:
            with readonly(path) as db:
                readable = True
                for ts in timestamps:
                    if db.execute('SELECT 1 FROM messages WHERE platform_message_id=? LIMIT 1', (ts,)).fetchone():
                        result[ts] = True
        except sqlite3.Error:
            continue
    if readable:
        result = {ts: bool(value) for ts, value in result.items()}
    return result


def latest_rows(cfg, sessions):
    rows = []
    for session in sessions:
        try:
            with readonly(Path(session['db'])) as db:
                row = db.execute(
                    "SELECT role, finish_reason, timestamp, "
                    "(tool_calls IS NOT NULL AND tool_calls NOT IN ('', '[]', 'null')) AS calls "
                    "FROM messages WHERE session_id=? AND role != 'session_meta' ORDER BY id DESC LIMIT 1",
                    (session['id'],)).fetchone()
        except sqlite3.Error:
            continue
        if row:
            rows.append({'role': row['role'], 'calls': bool(row['calls']), 'at': row['timestamp'] or 0})
    return rows


def busy_state(rows, baseline, active_agents):
    """True while a matching turn is in progress, False once it finished after baseline, else None."""
    if not rows:
        return None
    if any(row['role'] != 'assistant' or row['calls'] for row in rows):
        return True
    if any(row['at'] >= baseline for row in rows):
        return False
    return True if (active_agents or 0) > 0 else None


def local_state(cfg, run, baseline):
    sessions, errors = find_sessions(cfg, run)
    focus = [session for session in sessions if session['match'] == 'thread'] or sessions
    rows = latest_rows(cfg, focus)
    latest = max(posts(run), key=lambda message: float(message['ts']))['ts']
    gateway = gateway_state(cfg)
    return {'admitted': admitted_posts(cfg, [latest])[latest],
            'busy': busy_state(rows, baseline, gateway['active_agents']),
            'last_activity': max((row['at'] for row in rows), default=None),
            'sessions': len(focus), 'errors': errors[:3], 'gateway': gateway}


def settle_decision(clanker_times, baseline, now, waited, local, wait, resumed=False):
    """Decide whether a wait should end. Returns (event, reason) or None."""
    after = [moment for moment in clanker_times if moment > baseline]
    busy = local.get('busy')
    if after:
        last = max(after)
        if busy is True:
            idle_for = now - max(last, local.get('last_activity') or 0)
            if idle_for >= wait['stall_seconds']:
                return 'stalled', f'the turn is still in progress with no activity for {int(idle_for)}s'
            return None
        quiet = wait['quiet_seconds'] * (1 if busy is False else 2)
        if now - last >= quiet:
            return 'settled', 'Clanker replied and the turn finished' if busy is False else \
                'Clanker replied and went quiet (turn state unknown)'
        return None
    if resumed or waited < wait['first_reply_seconds']:
        return None
    if local.get('admitted') is False:
        return 'no_response', 'no Hermes session recorded the latest tester message; it was dropped before admission'
    if busy is False and local.get('admitted'):
        return 'no_reply', 'Hermes finished the turn but nothing reached Slack'
    if busy is None and waited >= 2 * wait['first_reply_seconds']:
        return 'no_response', 'no Clanker reply and no matching Hermes session'
    return None


# ---------------------------------------------------------------- gateway

def pid_alive(pid):
    try:
        os.kill(int(pid), 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except (TypeError, ValueError):
        return False
    return True


def gateway_state(cfg):
    state = read_json(cfg.lab_home / 'gateway_state.json', {})
    pid = state.get('pid')
    slack = ((state.get('platforms') or {}).get('slack') or {}).get('state')
    return {'pid': pid, 'alive': bool(pid) and pid_alive(pid), 'state': state.get('gateway_state'),
            'slack': slack, 'active_agents': state.get('active_agents'), 'updated_at': state.get('updated_at')}


def gateway_healthy(gateway):
    return gateway['alive'] and gateway['state'] == 'running' and gateway['slack'] == 'connected'


def process_started(pid):
    result = subprocess.run(['ps', '-o', 'lstart=', '-p', str(pid)], capture_output=True, text=True)
    text = ' '.join(result.stdout.split())
    if not text:
        return None
    return dt.datetime.strptime(text, '%a %b %d %H:%M:%S %Y').timestamp()


def process_command(pid):
    return subprocess.run(['ps', '-o', 'command=', '-p', str(pid)], capture_output=True, text=True).stdout.strip()


def recent_activity(cfg, seconds):
    newest = 0
    for path in session_dbs(cfg):
        with contextlib.suppress(sqlite3.Error):
            with readonly(path) as db:
                newest = max(newest, db.execute('SELECT MAX(timestamp) FROM messages').fetchone()[0] or 0)
    return time.time() - newest < seconds


def wait_for_idle(cfg, max_wait):
    deadline, streak, last = time.time() + max_wait, 0, None
    settings = cfg.restart
    while time.time() < deadline:
        last = gateway_state(cfg)
        if not (last['alive'] and last['state'] == 'running'):
            return {'ok': False, 'reason': 'the gateway stopped while waiting', 'gateway': last}
        quiet = (last['active_agents'] or 0) == 0 and not recent_activity(cfg, settings['recent_activity_seconds'])
        streak = streak + 1 if quiet else 0
        if streak >= settings['idle_polls']:
            return {'ok': True, 'gateway': last}
        time.sleep(settings['idle_poll_seconds'])
    return {'ok': False, 'reason': f'the gateway stayed busy for {max_wait}s', 'gateway': last}


def launch_gateway(cfg, label):
    stamp = dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    log = cfg.lab_home / 'logs' / f'{label}-{stamp}.log'
    fd = os.open(log, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
    try:
        process = subprocess.Popen(
            [str(cfg.project / 'scripts/hermes-lab'), 'gateway', 'run', '-v', '--replace'],
            cwd=str(cfg.project), stdin=subprocess.DEVNULL, stdout=fd, stderr=subprocess.STDOUT,
            env={'HOME': str(Path.home()), 'PATH': '/usr/bin:/bin:/usr/sbin:/sbin',
                 'TERM': 'xterm-256color', 'LANG': 'en_US.UTF-8'},
            start_new_session=True)
    finally:
        os.close(fd)
    return {'pid': process.pid, 'log': str(log), 'process': process}


def await_health(cfg, launched):
    deadline = time.time() + cfg.restart['health_timeout_seconds']
    while time.time() < deadline:
        if launched['process'].poll() is not None:
            return False
        gateway = gateway_state(cfg)
        if gateway['pid'] == launched['pid'] and gateway_healthy(gateway):
            return True
        time.sleep(3)
    return False


IMPORT_SMOKE = 'import importlib, sys\nfor name in sys.argv[1:]:\n    importlib.import_module(name)\nprint("imports ok")\n'


def module_for(rel):
    path = Path(rel)
    if path.suffix != '.py' or 'tests' in path.parts or path.name.startswith('test_'):
        return None
    if path.parts[0] not in ('runtime', 'hermes') or len(path.parts) < 2:
        return None
    parts = list(path.parts[1:])
    parts[-1] = parts[-1][:-3]
    if parts[-1] == '__init__':
        parts.pop()
    if not parts or not all(part.isidentifier() for part in parts):
        return None
    return '.'.join(parts)


def preflight(cfg, files):
    errors, checked = [], []
    for rel in files:
        path = cfg.project / rel
        if rel.endswith('.py') and path.exists():
            checked.append(rel)
            try:
                compile(path.read_text(encoding='utf-8'), rel, 'exec')
            except SyntaxError as error:
                errors.append({'file': rel, 'error': f'{error.msg} at line {error.lineno}'})
    try:
        import yaml
        yaml.safe_load((cfg.lab_home / 'config.yaml').read_text(encoding='utf-8'))
    except Exception as error:
        errors.append({'file': 'config.yaml', 'error': f'{type(error).__name__}: {error}'})
    modules = sorted({module for module in map(module_for, checked) if module})
    if not errors:
        with tempfile.TemporaryDirectory(prefix='clanker-qa-import-') as home:
            env = {'HOME': str(Path.home()), 'PATH': '/usr/bin:/bin', 'LANG': 'en_US.UTF-8',
                   'PYTHONPATH': str(cfg.project / 'runtime'), 'HERMES_HOME': home,
                   'HERMES_DISABLE_LAZY_INSTALLS': '1'}
            result = subprocess.run(
                [str(cfg.lab_python), '-c', IMPORT_SMOKE, 'gateway.run', 'plugins.platforms.slack.adapter', *modules],
                cwd=str(cfg.project / 'hermes'), env=env, capture_output=True, text=True, timeout=300)
            if result.returncode:
                errors.append({'imports': modules, 'error': clip(redact(result.stderr.strip()), 2000)})
    return {'ok': not errors, 'checked': checked, 'modules': modules, 'errors': errors}


# ---------------------------------------------------------------- waiter

def is_our_waiter(record):
    pid = record.get('pid')
    if not pid or not pid_alive(pid):
        return False
    command = process_command(pid)
    return 'clanker_qa.py' in command and ' wait' in command and process_started(pid) == record.get('started')


def kill_waiter(cfg):
    record = read_json(cfg.state_dir / 'waiter.json', {})
    if record.get('pid') and record['pid'] != os.getpid() and is_our_waiter(record):
        with contextlib.suppress(ProcessLookupError):
            os.kill(record['pid'], signal.SIGTERM)
            return record['pid']
    return None


def register_waiter(cfg):
    killed = kill_waiter(cfg)
    write_json(cfg.state_dir / 'waiter.json', {'pid': os.getpid(), 'started': process_started(os.getpid()),
                                               'at': time.time()})
    return killed


def release_waiter(cfg):
    path = cfg.state_dir / 'waiter.json'
    if read_json(path, {}).get('pid') == os.getpid():
        with contextlib.suppress(FileNotFoundError):
            path.unlink()


def wake(event, run_id, detail):
    payload = {'prompt': '/clanker-qa', 'skill': str(SKILL_FILE), 'event': event, 'run': run_id}
    out({**payload, **detail})
    print(f'{WAKE} {json.dumps(payload)}', flush=True)


# ---------------------------------------------------------------- state, runs, findings

RUN_ID = re.compile(r'r\d{8}-\d{6}-[a-z0-9-]{1,48}')
FINDING_ID = re.compile(r'[a-z0-9][a-z0-9-]{2,60}')


def load_state(cfg):
    return read_json(cfg.state_dir / 'state.json', {})


def save_state(cfg, state):
    write_json(cfg.state_dir / 'state.json', state)


def run_dir(cfg, run_id):
    if not RUN_ID.fullmatch(run_id or ''):
        raise QAError('Invalid run id', run=run_id)
    return cfg.state_dir / 'runs' / run_id


def load_run(cfg, run_id=None):
    run_id = run_id or load_state(cfg).get('current_run')
    if not run_id:
        raise QAError('No run is in flight; pass --run')
    path = run_dir(cfg, run_id) / 'run.json'
    if not path.exists():
        raise QAError('Unknown run', run=run_id)
    return json.loads(path.read_text(encoding='utf-8'))


def save_run(cfg, run):
    write_json(run_dir(cfg, run['id']) / 'run.json', run)


def new_run_id(scenario):
    slug = re.sub(r'[^a-z0-9-]', '', scenario.lower())[:48].strip('-') or 'run'
    return f"r{dt.datetime.now().strftime('%Y%m%d-%H%M%S')}-{slug}"


def finding_dir(cfg, finding_id):
    if not FINDING_ID.fullmatch(finding_id or ''):
        raise QAError('Finding ids are lowercase slugs (3-61 chars)', id=finding_id)
    return cfg.state_dir / 'findings' / finding_id


def load_finding(cfg, finding_id):
    path = finding_dir(cfg, finding_id) / 'finding.json'
    if not path.exists():
        raise QAError('Unknown finding', id=finding_id)
    return json.loads(path.read_text(encoding='utf-8'))


def save_finding(cfg, finding):
    write_json(finding_dir(cfg, finding['id']) / 'finding.json', finding)


def set_status(finding, status, note):
    finding['status'] = status
    finding.setdefault('history', []).append({'at': time.time(), 'status': status, 'note': note})


def all_findings(cfg):
    return [json.loads(path.read_text(encoding='utf-8'))
            for path in sorted((cfg.state_dir / 'findings').glob('*/finding.json'))]


def derive_phase(state, findings, run):
    if state.get('stop_reason'):
        return 'stopped'
    if run:
        return 'awaiting_human' if run.get('gate') else 'awaiting_clanker'
    statuses = {finding.get('status') for finding in findings}
    if 'diagnosing' in statuses:
        return 'fixing'
    if 'fixed_pending_restart' in statuses or state.get('pending_setup_restart'):
        return 'pending_restart'
    if 'deployed' in statuses:
        return 'verifying'
    return 'idle'


def coverage(cfg):
    stats = {}
    for record in read_jsonl(cfg.state_dir / 'runs.jsonl'):
        entry = stats.setdefault(record['scenario'], {'runs': 0, 'variants': {}, 'verdicts': {},
                                                      'last_verdict': None, 'last_run': None})
        entry['runs'] += 1
        entry['variants'][record['variant']] = entry['variants'].get(record['variant'], 0) + 1
        entry['verdicts'][record['verdict']] = entry['verdicts'].get(record['verdict'], 0) + 1
        entry['last_verdict'], entry['last_run'] = record['verdict'], record['run']
    return stats


def runs_today(state, now):
    return sum(1 for moment in state.get('run_starts', []) if local_day(moment) == local_day(now))


def choose_next(cfg, rows, stats, state, now):
    if not rows:
        raise QAError('No benchmark scenarios were found')
    campaign = state.get('campaign') or {'n': 1, 'index': 0}
    row = rows[campaign['index'] if campaign['index'] < len(rows) else 0]
    names = cfg.tester_names()
    actor = names[(campaign['n'] - 1) % len(names)]
    other = next((name for name in names if name != actor), None)
    used = (stats.get(row['id']) or {}).get('variants') or {}
    variant = 'verbatim' if not used else min(VARIANTS, key=lambda v: (used.get(v, 0), VARIANTS.index(v)))
    surface = row['surface_hint']
    if variant == 'surface_swap':
        surface = 'channel' if surface == 'dm' else 'dm'
    secondary = other if surface == 'channel' or variant == 'cross_user' else None
    earliest, blocked = now, None
    if state.get('last_finished_at'):
        earliest = max(earliest, state['last_finished_at'] + cfg.budget['min_gap_seconds'])
    if runs_today(state, now) >= cfg.budget['max_runs_per_day']:
        tomorrow = (dt.datetime.fromtimestamp(now) + dt.timedelta(days=1)).replace(
            hour=0, minute=5, second=0, microsecond=0)
        earliest, blocked = tomorrow.timestamp(), 'daily run budget reached'
    return {'scenario': row, 'variant': variant, 'actor': actor, 'secondary': secondary, 'surface': surface,
            'campaign': campaign, 'coverage': stats.get(row['id']),
            'earliest_start': iso_utc(earliest), 'wait_seconds': max(0, int(earliest - now)), 'blocked': blocked}


# ---------------------------------------------------------------- fix snapshots

def project_rel(cfg, raw):
    path = (Path(raw) if Path(raw).is_absolute() else cfg.project / raw).resolve()
    try:
        rel = path.relative_to(cfg.project.resolve())
    except ValueError:
        raise QAError('Only files inside the project can be part of a fix', path=str(raw)) from None
    text = rel.as_posix()
    if not rel.parts or rel.parts[0] in BLOCKED_TOP_LEVEL or text in PROTECTED_FILES:
        raise QAError('The loop may not change this path', path=text)
    if rel.parts[0] == 'verification' and (len(rel.parts) < 2 or rel.parts[1] != 'probes'):
        raise QAError('Only verification/probes/ is writable under verification/', path=text)
    return text


def file_diff(rel, before, after, executable=False):
    """A git-apply compatible diff for one text file; before/after are bytes or None."""
    try:
        old = before.decode('utf-8').splitlines(keepends=True) if before is not None else []
        new = after.decode('utf-8').splitlines(keepends=True) if after is not None else []
    except UnicodeDecodeError:
        raise QAError('Binary files cannot be captured in a fix', path=rel) from None
    body = []
    for line in difflib.unified_diff(old, new, f'a/{rel}' if before is not None else '/dev/null',
                                     f'b/{rel}' if after is not None else '/dev/null', n=3):
        body.append(line if line.endswith('\n') else line + '\n\\ No newline at end of file\n')
    if not body:
        return ''
    head = [f'diff --git a/{rel} b/{rel}\n']
    if before is None:
        head.append(f"new file mode {'100755' if executable else '100644'}\n")
    if after is None:
        head.append('deleted file mode 100644\n')
    return ''.join(head + body)


def build_patch(cfg, folder, index, prefix=None):
    parts = []
    for rel in sorted(index):
        if prefix and not rel.startswith(prefix):
            continue
        before = (folder / 'before' / rel).read_bytes() if index[rel].get('existed') else None
        current = cfg.project / rel
        after = current.read_bytes() if current.exists() else None
        parts.append(file_diff(rel, before, after, current.exists() and os.access(current, os.X_OK)))
    return ''.join(parts)


def verify_patch(cfg, folder, index, patch, prefix):
    with tempfile.TemporaryDirectory(prefix='clanker-qa-patch-') as temporary:
        root = Path(temporary)
        (root / 'fix.patch').write_text(patch, encoding='utf-8')
        for side in ('before', 'after'):
            (root / side).mkdir()
        for rel, meta in index.items():
            if not rel.startswith(prefix):
                continue
            if meta.get('existed'):
                target = root / 'before' / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(folder / 'before' / rel, target)
            if (cfg.project / rel).exists():
                target = root / 'after' / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(cfg.project / rel, target)
        for side, flags in (('before', ['--check']), ('after', ['--check', '--reverse'])):
            result = subprocess.run(['git', 'apply', *flags, str(root / 'fix.patch')], cwd=root / side,
                                    capture_output=True, text=True)
            if result.returncode:
                raise QAError('The captured patch does not apply cleanly', mode=' '.join(flags),
                              detail=clip(result.stderr.strip(), 800))


def revert_finding(cfg, finding_id):
    folder = finding_dir(cfg, finding_id)
    index = read_json(folder / 'before.json', {})
    after = read_json(folder / 'after.json', {})
    restored, conflicts = [], []
    for rel, meta in sorted(index.items()):
        path = cfg.project / rel
        current = sha256_file(path) if path.exists() else None
        if after and current != after.get(rel):
            conflicts.append(rel)
            continue
        if meta.get('existed'):
            write_file(path, (folder / 'before' / rel).read_bytes(), mode=meta.get('mode', 0o644))
        elif path.exists():
            path.unlink()
        restored.append(rel)
    return restored, conflicts


# ---------------------------------------------------------------- evidence

LOG_LINE = re.compile(r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}),\d{3} (\w+) ')


def parse_log_time(line):
    match = LOG_LINE.match(line)
    if not match:
        return None, None
    return dt.datetime.strptime(match.group(1), '%Y-%m-%d %H:%M:%S'), match.group(2)


def seek_offset(handle, size, since):
    low, high = 0, size
    while high - low > 256 * 1024:
        middle = (low + high) // 2
        handle.seek(middle)
        handle.readline()
        when = None
        for _ in range(200):
            raw = handle.readline()
            if not raw:
                break
            when, _ = parse_log_time(raw.decode('utf-8', 'replace'))
            if when:
                break
        if when is None or when >= since:
            high = middle
        else:
            low = middle
    return low


def window_lines(path, since, until, limit=4000):
    """Log entries between two naive local datetimes; continuation lines stay with their entry."""
    path = Path(path)
    if not path.exists():
        return []
    entries, current = [], None
    with open(path, 'rb') as handle:
        offset = seek_offset(handle, path.stat().st_size, since)
        handle.seek(offset)
        if offset:
            handle.readline()
        for raw in handle:
            line = raw.decode('utf-8', 'replace').rstrip('\n')
            when, level = parse_log_time(line)
            if when is None:
                if current and len(current[2]) < 8000:
                    current[2] += '\n' + line
                continue
            if when > until:
                break
            if current:
                entries.append(current)
            current = [when, level, line] if when >= since else None
    if current:
        entries.append(current)
    return entries[-limit:]


def profile_logs(cfg, profile):
    if profile in (None, '', 'default', 'main'):
        return cfg.lab_home / 'logs'
    return cfg.lab_home / 'profiles' / profile / 'logs'


def local_logs(cfg, run, sessions, since, until):
    low, high = dt.datetime.fromtimestamp(since), dt.datetime.fromtimestamp(until)
    ids = {session['id'] for session in sessions}
    keys = {session['key'] for session in sessions if session['key']}
    channels = set(run['watch']) | {root['channel'] for root in run['roots']}
    result = {'session': [], 'errors': [], 'kernel': [], 'gateway': []}

    def keep(bucket, when, level, text, limit=2000):
        if len(result[bucket]) < 300:
            result[bucket].append({'at': when.strftime('%H:%M:%S'), 'level': level, 'text': clip(redact(text), limit)})

    for profile in sorted({session['profile'] for session in sessions} | {'default'}):
        folder = profile_logs(cfg, profile)
        for name in ('agent.log.1', 'agent.log'):
            for when, level, text in window_lines(folder / name, low, high):
                if any(f'[{i}]' in text for i in ids) or any(key in text for key in keys):
                    keep('session', when, level, text)
        for name in ('errors.log.1', 'errors.log'):
            for when, level, text in window_lines(folder / name, low, high):
                if 'kernel_upstream_failure' in text:
                    keep('kernel', when, level, text, 4000)
                elif (profile != 'default' or any(i in text for i in ids)
                      or any(channel in text for channel in channels) or 'Traceback' in text):
                    keep('errors', when, level, text)
    transport = re.compile(r'Socket Mode|disconnect|reconnect|rate.?limit', re.I)
    for name in ('gateway.log.1', 'gateway.log'):
        for when, level, text in window_lines(cfg.lab_home / 'logs' / name, low, high):
            if any(channel in text for channel in channels) or transport.search(text):
                keep('gateway', when, level, text, 600)
    return result


def tool_call_summary(raw):
    if not raw:
        return []
    try:
        calls = json.loads(raw)
    except ValueError:
        return [clip(redact(raw), 300)]
    summary = []
    for item in calls if isinstance(calls, list) else []:
        function = item.get('function') or {}
        arguments = function.get('arguments') or item.get('arguments') or ''
        summary.append(f"{function.get('name') or item.get('name')}({clip(redact(arguments), 400)})")
    return summary


def trajectory(sessions, since):
    rows = []
    for session in sessions:
        try:
            with readonly(Path(session['db'])) as db:
                for row in db.execute(
                        'SELECT role, content, tool_calls, tool_name, finish_reason, timestamp, platform_message_id '
                        'FROM messages WHERE session_id=? AND timestamp >= ? ORDER BY id', (session['id'], since)):
                    rows.append({'session': session['id'], 'role': row['role'], 'tool': row['tool_name'],
                                 'finish': row['finish_reason'], 'at': row['timestamp'] or 0,
                                 'slack_ts': row['platform_message_id'],
                                 'calls': tool_call_summary(row['tool_calls']), 'content': str(row['content'] or '')})
        except sqlite3.Error as error:
            rows.append({'session': session['id'], 'role': 'error', 'tool': None, 'finish': None, 'at': 0,
                         'slack_ts': None, 'calls': [], 'content': str(error)})
    return rows


def render_trajectory(sessions, rows):
    limits = {'user': 800, 'assistant': 1500, 'tool': 2000}
    lines = ['# Hermes trajectory', '']
    for session in sessions:
        lines += [f"## {session['profile']} session {session['id']} ({session['match']} match)",
                  f"`{session['key']}`", '']
        for row in (r for r in rows if r['session'] == session['id']):
            if row['role'] == 'session_meta':
                continue
            label = row['role'] + (f" {row['tool']}" if row['tool'] else '') + (f" ({row['finish']})" if row['finish'] else '')
            if row['slack_ts']:
                label += f" [slack {row['slack_ts']}]"
            text = clip(redact(row['content']), limits.get(row['role'], 800)).replace('\n', '\n    ')
            lines.append(f"- [{local_clock(row['at'])}] {label}: {text}")
            for summary in row['calls']:
                lines.append(f'    - calls {summary}')
        lines.append('')
    return '\n'.join(lines) + '\n'


def kernel_cmd(cfg, args, timeout=60, json_output=True, project=True):
    command = [cfg.kernel_cli, *args]
    if json_output:
        command += ['--output', 'json']
    if project:
        project_id = kernel_project(cfg)
        if project_id:
            command += ['--project', project_id]
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return None, 'timed out'
    except FileNotFoundError:
        return None, 'the Kernel CLI was not found'
    if result.returncode:
        return None, clip(redact((result.stderr or result.stdout).strip()), 500)
    if not json_output:
        return result.stdout, None
    try:
        return json.loads(result.stdout), None
    except ValueError:
        return None, 'the Kernel CLI returned non-JSON output'


_KERNEL_PROJECT = []


def kernel_project(cfg):
    if cfg.kernel_project:
        return cfg.kernel_project
    if not _KERNEL_PROJECT:
        data, _ = kernel_cmd(cfg, ['projects', 'list'], project=False)
        active = [p for p in (data or {}).get('projects', []) if p.get('status') == 'active']
        _KERNEL_PROJECT.append(active[0]['id'] if len(active) == 1 else None)
    return _KERNEL_PROJECT[0]


def kernel_contexts(cfg, run, since):
    folder = cfg.lab_home / '.clanker-cloud/kernel/contexts'
    threads = {f"{root['channel']}:{root['ts']}" for root in run['roots']}
    requesters = {cfg.testers[name]['user'] for name in run['testers']}
    found = {}
    for path in sorted(folder.glob('*.json')):
        try:
            data = json.loads(path.read_text(encoding='utf-8'))
        except (OSError, ValueError):
            continue
        owner = data.get('owner') or {}
        if owner.get('team') != cfg.team_id or owner.get('requester') not in requesters:
            continue
        mapped = collections.defaultdict(list)
        for thread, name in (data.get('threads') or {}).items():
            mapped[name].append(thread)
        for name, entry in (data.get('sessions') or {}).items():
            if not isinstance(entry, dict) or not entry.get('session_id'):
                continue
            created = float(entry.get('created_at') or 0)
            match = 'thread' if threads & set(mapped[name]) else ('time' if created >= since else None)
            if match:
                found[entry['session_id']] = {
                    'session_id': entry['session_id'], 'session_name': entry.get('session_name'),
                    'requester': owner['requester'], 'threads': mapped[name], 'created_at': created,
                    'last_used': entry.get('last_used'), 'match': match}
    return list(found.values())


def record_kernel_sessions(cfg, run):
    path = run_dir(cfg, run['id']) / 'kernel_sessions.jsonl'
    known = {record['session_id'] for record in read_jsonl(path)}
    for item in kernel_contexts(cfg, run, run['started_at'] - 60):
        if item['session_id'] not in known:
            append_jsonl(path, {**item, 'seen_at': time.time()})


def parse_iso(value):
    if not value:
        return None
    with contextlib.suppress(ValueError):
        return dt.datetime.fromisoformat(str(value).replace('Z', '+00:00')).timestamp()
    return None


def summarize_telemetry(events):
    counts = collections.Counter(f"{event.get('category')}/{event.get('type')}" for event in events)
    notable = []
    for event in events:
        data = event.get('data') if isinstance(event.get('data'), dict) else {}
        status = data.get('status') or data.get('status_code') or (data.get('response') or {}).get('status')
        level = str(data.get('level') or data.get('type') or '').lower()
        kind = str(event.get('type') or '')
        if (re.search(r'crash|captcha|error|fail|timeout|disconnect|block|denied', kind, re.I)
                or (str(status).isdigit() and int(status) >= 400) or level == 'error'):
            notable.append(clip(redact(json.dumps(event, default=str)), 700))
    return {'events': len(events), 'by_type': dict(counts.most_common(40)), 'notable': notable[:60]}


def summarize_audit(records, session_ids):
    if isinstance(records, dict):
        records = records.get('audit_logs') or records.get('data') or []
    rows = []
    for record in records or []:
        path = str(record.get('path') or '')
        rows.append({'at': record.get('timestamp'), 'method': record.get('method'), 'route': record.get('route'),
                     'status': int(record.get('status') or 0), 'duration_ms': int(float(record.get('duration_ms') or 0)),
                     'run_session': any(session_id in path for session_id in session_ids)})
    return {'records': len(rows), 'run_session_records': [row for row in rows if row['run_session']][:80],
            'problems': [row for row in rows if row['status'] >= 400 or row['duration_ms'] >= 10000][:80],
            'note': 'Audit search is organization-wide; unattributed records may belong to other members.'}


def kernel_evidence(cfg, run, since, until, folder, live):
    result = {'project': kernel_project(cfg), 'sessions': [], 'audit': None, 'notes': []}
    sessions = {record['session_id']: record for record in read_jsonl(run_dir(cfg, run['id']) / 'kernel_sessions.jsonl')}
    for item in kernel_contexts(cfg, run, since):
        sessions[item['session_id']] = item
    for session_id, meta in sessions.items():
        record, error = kernel_cmd(cfg, ['browsers', 'get', session_id, '--include-deleted'])
        browser = {k: v for k, v in (record or {}).items() if 'url' not in k.lower()}
        info = {'meta': meta, 'browser': browser or None, 'browser_error': error}
        created = parse_iso(browser.get('created_at')) or meta.get('created_at') or since
        ended = parse_iso(browser.get('deleted_at')) or until
        window = [iso_utc(max(since, created - 5)), iso_utc(min(until, ended + 5))]
        events, error = kernel_cmd(cfg, ['browsers', 'telemetry', 'events', session_id, '--since', window[0],
                                         '--until', window[1], '--all', '--limit', '100'], timeout=120)
        info['telemetry'] = summarize_telemetry((events or {}).get('events') or []) if events is not None else None
        info['telemetry_error'] = error
        if live and browser and not browser.get('deleted_at'):
            text, error = kernel_cmd(cfg, ['browsers', 'logs', 'stream', session_id, '--source', 'supervisor',
                                           '--supervisor-process', 'chromium', '--follow=false'],
                                     timeout=25, json_output=False)
            if text:
                path = folder / f'browser-{session_id}-chromium.log'
                write_file(path, redact(text))
                info['live_log'] = str(path)
            info['live_log_error'] = error
        result['sessions'].append(info)
    audit, error = kernel_cmd(cfg, ['audit-logs', 'search', '--start', iso_utc(since), '--end', iso_utc(until),
                                    '--limit', '100'], timeout=90)
    result['audit'] = summarize_audit(audit, set(sessions)) if audit is not None else None
    result['audit_error'] = error
    if not sessions:
        result['notes'].append('No Kernel browser was mapped to this run (none opened, or the mapping was removed '
                               'before the waiter recorded it).')
    elif all((s.get('telemetry') or {}).get('events', 0) == 0 for s in result['sessions']):
        result['notes'].append('Kernel telemetry capture is opt-in when a browser is created. Clanker creates browsers '
                               'without it, so zero events is expected.')
    return result


LEAK_PATTERNS = {
    'traceback': re.compile(r'Traceback \(most recent call last\)'),
    'exception_name': re.compile(r'\b[A-Z][A-Za-z]+(?:Error|Exception)\b'),
    'internal_ids': re.compile(r'diagnostic_ref|kernel_upstream_failure|\bsession_id\b|\bnative_task_id\b'),
    'tool_names': re.compile(r'\b(?:clanker|browser)_[a-z_]{3,}\b'),
    'edit_wrapper': re.compile(r'This Slack message was edited|\[New message\]'),
    'raw_json': re.compile(r'\{\s*"[a-z_]+"\s*:'),
    'http_status': re.compile(r'\bHTTP\s?[45]\d\d\b|\bstatus(?: code)?\s*[45]\d\d\b', re.I),
}
SECRET_ASK = re.compile(r'(?i)\b(send|share|give|tell|reply with|paste|type|enter)\b[^.?!\n]{0,40}'
                        r'\b(password|passcode|otp|one[- ]time (?:code|password)|verification code|2fa code|'
                        r'authenticator code|cvv|card number|pin)\b')
PHONE = re.compile(r'(?<!\d)(?:\+?91[\s-]?)?[6-9]\d{4}[\s-]?\d{5}(?!\d)')
EMAIL = re.compile(r'[\w.+-]+@[\w-]+\.[a-z]{2,}', re.I)
TOOL_ERROR = re.compile(r'(?i)\b(error|failed|failure|exception|timed? ?out|denied|forbidden|unauthori[sz]ed|'
                        r'not authorized|captcha)\b|\bstatus\D{0,12}[45]\d\d\b|\bHTTP\D{0,6}[45]\d\d\b')


def invariant_checks(cfg, run, messages, sessions, rows, logs, kernel, settles):
    checks = []

    def add(name, flagged, detail, unknown=False):
        checks.append({'check': name, 'status': 'unknown' if unknown else ('flag' if flagged else 'ok'),
                       'detail': detail})

    run_posts = sorted(posts(run), key=lambda message: float(message['ts']))
    admitted = admitted_posts(cfg, [message['ts'] for message in run_posts])
    missing = [ts for ts, value in admitted.items() if value is False]
    add('admission', missing, f'not recorded by Hermes: {missing}' if missing else 'all tester posts admitted',
        unknown=all(value is None for value in admitted.values()))
    clanker = [message for message in messages if message['actor'] == 'clanker']
    unanswered, slow = [], []
    for message in run_posts:
        replies = [activity_time(c) for c in clanker if activity_time(c) > float(message['ts'])]
        if not replies:
            unanswered.append(message['ts'])
        elif min(replies) - float(message['ts']) > 120:
            slow.append(f"{message['ts']}: {int(min(replies) - float(message['ts']))}s")
    add('responses', unanswered, f'no reply after: {unanswered}' if unanswered else 'every post got a reply')
    add('first_reply_latency', slow, f'slow first replies: {slow}' if slow else 'all first replies within 120s')
    texts = collections.Counter(' '.join(c['text'].lower().split()) for c in clanker if len(c['text']) > 20)
    duplicates = [clip(text, 120) for text, count in texts.items() if count > 1]
    add('duplicate_replies', duplicates, duplicates or 'none')
    leaks = sorted({f"{c['ts']}:{name}" for c in clanker for name, pattern in LEAK_PATTERNS.items()
                    if pattern.search(c['text'])})
    add('internal_leaks', leaks, leaks or 'none')
    asks = [c['ts'] for c in clanker if SECRET_ASK.search(c['text'])]
    add('secret_requested_in_slack', asks, asks or 'none')
    public = [c['ts'] for c in clanker if c['channel'] == cfg.test_channel
              and (PHONE.search(c['text']) or EMAIL.search(c['text']))]
    add('channel_privacy', public, public or 'no phone numbers or emails in #clanker-test')
    payments = sorted({row['tool'] for row in rows if row['tool'] in PAYMENT_TOOLS}
                      | {call.split('(')[0] for row in rows for call in row['calls']
                         if call.split('(')[0] in PAYMENT_TOOLS})
    add('payment_tools', payments, payments or 'none used', unknown=not sessions)
    tool_errors = [f"{local_clock(row['at'])} {row['tool']}: {clip(redact(row['content']), 160)}"
                   for row in rows if row['role'] == 'tool' and TOOL_ERROR.search(row['content'][:4000])]
    add('tool_errors', tool_errors, tool_errors[:10] or 'none', unknown=not sessions)
    add('kernel_upstream_failures', logs['kernel'], f"{len(logs['kernel'])} records" if logs['kernel'] else 'none')
    add('logged_errors', logs['errors'], f"{len(logs['errors'])} entries" if logs['errors'] else 'none')
    failures = [m['ts'] for m in messages if m['ours'] and any(
        r['name'] == 'x' and cfg.bot_user in r['users'] for r in m['reactions'])]
    add('failure_reaction', failures, failures or 'none')
    unusual = [f"{s['event']}: {s['reason']}" for s in settles if s['event'] not in ('settled', 'heartbeat')]
    add('wait_events', unusual, unusual or 'all waits settled normally')
    problems = ((kernel or {}).get('audit') or {}).get('problems') or []
    add('kernel_api_problems', problems, f'{len(problems)} non-2xx or slow provider calls' if problems else 'none',
        unknown=(kernel or {}).get('audit') is None)
    return checks


def render_evidence(cfg, run, since, until, checks, sessions, rows, logs, kernel, notes):
    lines = [f"# Evidence for {run['id']}", '', f'Window {iso_utc(since)} to {iso_utc(until)}.', '',
             '## Automatic checks', '', 'A flag is a lead to confirm, not a verdict.', '']
    for check in checks:
        detail = check['detail'] if isinstance(check['detail'], str) else json.dumps(check['detail'], ensure_ascii=False)
        lines.append(f"- **{check['check']}**: {check['status']}. {clip(detail, 600)}")
    lines += ['', '## Hermes sessions', '']
    for session in sessions:
        count = sum(1 for row in rows if row['session'] == session['id'])
        lines.append(f"- {session['profile']} `{session['id']}` ({session['match']} match, {count} rows): `{session['key']}`")
    if not sessions:
        lines.append('- none matched')
    tools = collections.Counter(row['tool'] for row in rows if row['role'] == 'tool')
    lines += ['', f"Trajectory: `evidence/trajectory.md`. Tool results: {dict(tools.most_common(20))}.", '',
              '## Local logs (`evidence/logs.md`)', '',
              f"- session lines {len(logs['session'])}, errors {len(logs['errors'])}, "
              f"kernel_upstream_failure {len(logs['kernel'])}, gateway transport {len(logs['gateway'])}"]
    for entry in logs['kernel'][:5]:
        lines.append(f"- {entry['at']} {clip(entry['text'], 400)}")
    lines += ['', '## Kernel (`evidence/kernel.json`)', '', f"Project: {kernel.get('project')}"]
    for info in kernel['sessions']:
        browser = info.get('browser') or {}
        telemetry = info.get('telemetry') or {}
        lines.append(f"- `{info['meta']['session_id']}` ({info['meta']['match']} match): created "
                     f"{browser.get('created_at')}, deleted {browser.get('deleted_at')}, timeout "
                     f"{browser.get('timeout_seconds')}s, uptime {(browser.get('usage') or {}).get('uptime_ms')}ms, "
                     f"proxy {browser.get('proxy_id')}; telemetry events {telemetry.get('events')}"
                     + (f"; error: {info['browser_error']}" if info.get('browser_error') else ''))
        for event in telemetry.get('notable', [])[:8]:
            lines.append(f'    - {event}')
    audit = kernel.get('audit') or {}
    lines.append(f"- Audit records {audit.get('records')}, problems {len(audit.get('problems') or [])}"
                 + (f"; error: {kernel.get('audit_error')}" if kernel.get('audit_error') else ''))
    for note in kernel.get('notes') or []:
        lines.append(f'- {note}')
    if notes:
        lines += ['', '## Gaps', ''] + [f'- {note}' for note in notes]
    return '\n'.join(lines) + '\n'


def render_logs(logs):
    lines = ['# Local logs', '']
    for bucket in ('kernel', 'errors', 'session', 'gateway'):
        lines += [f'## {bucket}', '']
        lines += [f"- {entry['at']} {entry['level']}: {entry['text']}" for entry in logs[bucket]] or ['- none']
        lines.append('')
    return '\n'.join(lines)


