def cmd_start(cfg, args):
    state = load_state(cfg)
    if state.get('stop_reason'):
        raise QAError('The loop is stopped; run resume first', reason=state['stop_reason'])
    if state.get('current_run') and not args.force:
        raise QAError('A run is already in flight; finish it first', run=state['current_run'])
    scenario = scenario_for(cfg, args.scenario, args.text)
    if args.verify:
        load_finding(cfg, args.verify)
    now = time.time()
    if not args.verify and not args.force:
        if runs_today(state, now) >= cfg.budget['max_runs_per_day']:
            raise QAError('The daily run budget is used up', max_runs_per_day=cfg.budget['max_runs_per_day'])
        gap = (state.get('last_finished_at') or 0) + cfg.budget['min_gap_seconds'] - now
        if gap > 0:
            raise QAError(f'Wait {int(gap)}s before the next run (min_gap_seconds)')
    gateway = gateway_state(cfg)
    if not gateway_healthy(gateway):
        raise QAError('The Clanker gateway is not healthy', gateway=gateway)
    if args.secondary == args.actor:
        raise QAError('The secondary tester must differ from the actor')
    testers = [args.actor] + ([args.secondary] if args.secondary else [])
    channel = tester_dm(cfg, args.actor) if args.surface == 'dm' else cfg.test_channel
    text = args.text or scenario['initial']
    if args.surface == 'channel' and f'<@{cfg.bot_user}>' not in text:
        text = f'<@{cfg.bot_user}> {text}'
    watch = sorted({channel, *(tester_dm(cfg, name) for name in testers)})
    ts = post_message(cfg, args.actor, channel, text)
    run = {'id': new_run_id(scenario['id']), 'scenario': scenario['id'], 'scenario_text': scenario['initial'],
           'followups': scenario['followups'], 'sent_followups': [], 'variant': args.variant, 'surface': args.surface,
           'actor': args.actor, 'secondary': args.secondary, 'testers': testers, 'watch': watch,
           'roots': [{'channel': channel, 'ts': ts}], 'started_at': float(ts), 'verify': args.verify,
           'campaign': (state.get('campaign') or {}).get('n', 1),
           'messages': [{'ts': ts, 'channel': channel, 'thread': None, 'actor': args.actor, 'text': text,
                         'kind': 'initial', 'at': time.time()}]}
    save_run(cfg, run)
    state['current_run'] = run['id']
    state['run_starts'] = (state.get('run_starts') or [])[-300:] + [now]
    save_state(cfg, state)
    out({'run': run['id'], 'posted': ts, 'where': channel_label(cfg, channel), 'permalink': permalink(cfg, channel, ts),
         'next': f"arm: wait --run {run['id']}"})


def cmd_send(cfg, args):
    run = load_run(cfg, args.run)
    if run.get('verdict'):
        raise QAError('This run is finished')
    actor = args.actor or run['actor']
    if actor not in run['testers']:
        raise QAError('That tester is not part of this run; start the run with --secondary')
    if len(posts(run)) >= cfg.budget['max_messages_per_run'] and not args.force:
        raise QAError('This run reached max_messages_per_run; finish it')
    if args.top_level:
        channel, thread = (tester_dm(cfg, actor) if args.top_level == 'dm' else cfg.test_channel), None
    else:
        root = next((r for r in run['roots'] if r['ts'] == args.root), None) if args.root else run['roots'][-1]
        if not root:
            raise QAError('Unknown root', root=args.root)
        channel, thread = root['channel'], root['ts']
    text = args.text
    if channel == cfg.test_channel and (args.mention or thread is None) and f'<@{cfg.bot_user}>' not in text:
        text = f'<@{cfg.bot_user}> {text}'
    ts = post_message(cfg, actor, channel, text, thread)
    run['messages'].append({'ts': ts, 'channel': channel, 'thread': thread, 'actor': actor, 'text': text,
                            'kind': args.kind, 'followup': args.followup, 'at': time.time()})
    if thread is None:
        run['roots'].append({'channel': channel, 'ts': ts})
        run['watch'] = sorted(set(run['watch']) | {channel})
    if args.followup is not None:
        run['sent_followups'] = sorted(set(run.get('sent_followups', [])) | {args.followup})
    run.pop('gate', None)
    save_run(cfg, run)
    out({'run': run['id'], 'posted': ts, 'where': channel_label(cfg, channel),
         'permalink': permalink(cfg, channel, ts, thread), 'next': f"arm: wait --run {run['id']}"})


