def cmd_wait(cfg, args):
    killed = register_waiter(cfg)
    try:
        if args.idle is not None:
            deadline = time.time() + max(5, min(args.idle, 6 * 3600))
            while time.time() < deadline:
                if load_state(cfg).get('stop_reason'):
                    return
                time.sleep(min(15, max(0, deadline - time.time())))
            return wake('heartbeat', load_state(cfg).get('current_run'), {'replaced_waiter': killed})
        run = load_run(cfg, args.run)
        settings = dict(cfg.wait)
        for key in ('quiet', 'timeout', 'first_reply', 'heartbeat'):
            if getattr(args, key) is not None:
                settings[f'{key}_seconds'] = getattr(args, key)
        resumed = args.after is not None
        baseline = time.time() if args.after == 'now' else float(args.after) if args.after else last_tester_activity(run)
        started, unhealthy, failures = time.time(), 0, 0
        folder = run_dir(cfg, run['id'])
        while True:
            if load_state(cfg).get('stop_reason'):
                return
            now = time.time()
            waited = now - started
            try:
                messages, notes = collect(cfg, run)
                local = local_state(cfg, run, baseline)
                failures = 0
            except QAError as error:
                failures += 1
                if failures >= 5:
                    return wake('infra_error', run['id'], {'error': str(error), **error.detail})
                time.sleep(settings['poll_seconds'])
                continue
            with contextlib.suppress(OSError, ValueError):
                record_kernel_sessions(cfg, run)
            clanker = [m for m in messages if m['actor'] == 'clanker']
            decision = settle_decision([activity_time(m) for m in clanker], baseline, now, waited, local,
                                       settings, resumed)
            gateway = local['gateway']
            unhealthy = 0 if gateway_healthy(gateway) else unhealthy + 1
            if not decision and unhealthy >= 3:
                decision = ('gateway_down', f"gateway state {gateway['state']}, Slack {gateway['slack']}")
            if not decision and waited >= settings['timeout_seconds']:
                decision = ('timeout', f'no settled turn after {int(waited)}s')
            if not decision and waited >= settings['heartbeat_seconds']:
                decision = ('heartbeat', 'still waiting; check progress and re-arm')
            if decision:
                event, reason = decision
                append_jsonl(folder / 'settles.jsonl', {'event': event, 'reason': reason, 'at': now,
                                                        'baseline': baseline, 'waited': int(waited)})
                fresh = [m for m in clanker if activity_time(m) > baseline]
                return wake(event, run['id'], {
                    'reason': reason, 'waited_seconds': int(waited), 'clanker_messages_since_baseline': len(fresh),
                    'last_clanker_text': clip(fresh[-1]['text'], 300) if fresh else None,
                    'gate_hints': gate_hints(fresh), 'local': {k: local[k] for k in ('admitted', 'busy', 'sessions')},
                    'retrieval_gaps': notes, 'replaced_waiter': killed})
            time.sleep(settings['poll_seconds'])
    finally:
        release_waiter(cfg)


