def cmd_finish(cfg, args):
    state = load_state(cfg)
    run = load_run(cfg, args.run)
    if run.get('verdict'):
        raise QAError('This run is already finished', verdict=run['verdict'])
    for finding_id in args.finding or []:
        load_finding(cfg, finding_id)
    run.update(verdict=args.verdict, summary=args.summary, findings=args.finding or [], finished_at=time.time())
    run.pop('gate', None)
    save_run(cfg, run)
    append_jsonl(cfg.state_dir / 'runs.jsonl', {
        'run': run['id'], 'scenario': run['scenario'], 'variant': run['variant'], 'surface': run['surface'],
        'actor': run['actor'], 'secondary': run.get('secondary'), 'verdict': args.verdict, 'verify': run.get('verify'),
        'findings': run['findings'], 'started_at': run['started_at'], 'finished_at': run['finished_at'],
        'campaign': run.get('campaign')})
    for finding_id in args.finding or []:
        finding = load_finding(cfg, finding_id)
        finding['runs'] = sorted(set(finding.get('runs', [])) | {run['id']})
        save_finding(cfg, finding)
    verified = None
    if run.get('verify'):
        finding = load_finding(cfg, run['verify'])
        finding['runs'] = sorted(set(finding.get('runs', [])) | {run['id']})
        if args.verdict == 'pass':
            set_status(finding, 'verified', f"verified by {run['id']}")
        elif args.verdict == 'fail':
            finding['attempts'] = finding.get('attempts', 0) + 1
            set_status(finding, 'needs_human' if finding['attempts'] >= 3 else 'diagnosing',
                       f"verification {run['id']} failed (attempt {finding['attempts']})")
        save_finding(cfg, finding)
        verified = {'finding': finding['id'], 'status': finding['status']}
    rows = load_rows(cfg)
    campaign = state.setdefault('campaign', {'n': 1, 'index': 0})
    if not run.get('verify') and rows and campaign['index'] < len(rows) and rows[campaign['index']]['id'] == run['scenario']:
        campaign['index'] += 1
        if campaign['index'] >= len(rows):
            campaign.update(n=campaign['n'] + 1, index=0)
    if state.get('current_run') == run['id']:
        state['current_run'] = None
    state['last_finished_at'] = time.time()
    recent = [r['verdict'] for r in read_jsonl(cfg.state_dir / 'runs.jsonl')[-3:]]
    save_state(cfg, state)
    out({'run': run['id'], 'verdict': args.verdict, 'verification': verified, 'campaign': campaign,
         'three_infra_in_a_row': len(recent) == 3 and set(recent) == {'infra'}})


def cmd_finding(cfg, args):
    if args.action == 'list':
        needle = (args.search or '').lower()
        found = [f for f in all_findings(cfg) if (not args.status or f['status'] == args.status)
                 and (not needle or needle in json.dumps({k: f.get(k) for k in ('id', 'title', 'fingerprint', 'summary')}).lower())]
        return out({'findings': [{k: f.get(k) for k in ('id', 'title', 'severity', 'fingerprint', 'status', 'attempts', 'runs')}
                                 for f in found]})
    if args.action == 'show':
        return out(load_finding(cfg, args.id))
    if args.action == 'add':
        folder = finding_dir(cfg, args.id)
        if (folder / 'finding.json').exists():
            raise QAError('That finding exists; use finding update', id=args.id)
        if not args.title:
            raise QAError('A new finding needs --title')
        finding = {'id': args.id, 'title': args.title, 'severity': args.severity or 'S2',
                   'fingerprint': args.fingerprint or args.id, 'summary': args.summary, 'root_cause': args.root_cause,
                   'runs': [args.run] if args.run else [], 'files': [], 'tests': [], 'decision_doc': None,
                   'attempts': 0, 'created_at': time.time()}
        set_status(finding, 'diagnosing', args.note or 'opened')
        save_finding(cfg, finding)
        return out({'finding': finding['id'], 'status': finding['status']})
    finding = load_finding(cfg, args.id)
    for field in ('title', 'severity', 'fingerprint', 'summary', 'root_cause', 'decision_doc'):
        if getattr(args, field, None):
            finding[field] = getattr(args, field)
    if args.run:
        finding['runs'] = sorted(set(finding.get('runs', [])) | {args.run})
    if args.tests:
        finding['tests'] = args.tests
    if args.status and args.status != finding['status']:
        set_status(finding, args.status, args.note or 'updated')
    elif args.note:
        finding.setdefault('history', []).append({'at': time.time(), 'status': finding['status'], 'note': args.note})
    save_finding(cfg, finding)
    out({'finding': finding['id'], 'status': finding['status']})


def cmd_snapshot(cfg, args):
    load_finding(cfg, args.finding)
    folder = finding_dir(cfg, args.finding)
    index = read_json(folder / 'before.json', {})
    added = []
    for raw in args.paths:
        rel = project_rel(cfg, raw)
        if rel in index:
            continue
        path = cfg.project / rel
        if path.exists():
            if not path.is_file():
                raise QAError('Snapshots cover files only', path=rel)
            data = path.read_bytes()
            write_file(folder / 'before' / rel, data)
            index[rel] = {'existed': True, 'sha256': hashlib.sha256(data).hexdigest(), 'mode': path.stat().st_mode & 0o777}
        else:
            index[rel] = {'existed': False}
        added.append(rel)
    write_json(folder / 'before.json', index)
    out({'finding': args.finding, 'snapshotted': added, 'tracked': sorted(index)})


def cmd_diff(cfg, args):
    folder = finding_dir(cfg, args.finding)
    index = read_json(folder / 'before.json', {})
    if not index:
        raise QAError('Nothing is snapshotted for this finding')
    result = {'finding': args.finding}
    if args.hermes_patch:
        name = args.hermes_patch if args.hermes_patch.endswith('.patch') else args.hermes_patch + '.patch'
        if not re.fullmatch(r'[a-z0-9][a-z0-9-]*\.patch', name):
            raise QAError('Patch names are lowercase slugs', name=name)
        patch = build_patch(cfg, folder, index, prefix='hermes/')
        if not patch:
            raise QAError('No hermes/ file changed')
        verify_patch(cfg, folder, index, patch, 'hermes/')
        rel = f'patches/hermes/{name}'
        if (cfg.project / rel).exists() and rel not in index:
            raise QAError('That patch file already exists', path=rel)
        if rel not in index:
            index[rel] = {'existed': False}
            write_json(folder / 'before.json', index)
        write_file(cfg.project / rel, patch, mode=0o644)
        result.update(hermes_patch=rel, register=f"patches.append(root / '{rel}')",
                      register_in='scripts/apply-hermes-mods (snapshot it first)')
    patch = build_patch(cfg, folder, index)
    write_file(folder / 'fix.patch', patch)
    result.update(fix_patch=str(folder / 'fix.patch'), files=sorted(index), lines=patch.count('\n'))
    out(result)


