    index = read_json(folder / 'before.json', {})
    if not index:
        raise QAError('Snapshot files before editing them')
    after, changed = {}, []
    for rel, meta in index.items():
        path = cfg.project / rel
        after[rel] = sha256_file(path) if path.exists() else None
        if after[rel] != meta.get('sha256'):
            changed.append(rel)
    if not changed:
        raise QAError('No tracked file changed')
    write_json(folder / 'after.json', after)
    write_file(folder / 'fix.patch', build_patch(cfg, folder, index))
    finding.update(files=sorted(changed), fixed_at=time.time())
    if args.tests:
        finding['tests'] = args.tests
    if args.decision_doc:
        finding['decision_doc'] = args.decision_doc
    set_status(finding, 'fixed_pending_restart', args.note or 'fix ready')
    save_finding(cfg, finding)
    out({'finding': finding['id'], 'status': finding['status'], 'files': finding['files'],
         'fix_patch': str(folder / 'fix.patch')})


def cmd_revert(cfg, args):
    finding = load_finding(cfg, args.finding)
    restored, conflicts = revert_finding(cfg, args.finding)
    set_status(finding, 'diagnosing', args.note or 'fix reverted')
    save_finding(cfg, finding)
    out({'finding': finding['id'], 'restored': restored, 'conflicts': conflicts})


def cmd_restart(cfg, args):
    state = load_state(cfg)
    pending = [f for f in all_findings(cfg) if f['status'] == 'fixed_pending_restart']
    setup = bool(state.get('pending_setup_restart'))
    if not pending and not setup and not args.force:
        raise QAError('Nothing needs a restart')
    if state.get('current_run'):
        raise QAError('Finish the current run before restarting', run=state['current_run'])
    gateway = gateway_state(cfg)
    if not (gateway['alive'] and gateway['state'] == 'running'):
        raise QAError('The gateway is not running; the loop does not start it', gateway=gateway)
    files = sorted({rel for finding in pending for rel in finding.get('files', [])})
    checked = preflight(cfg, files)
    if not checked['ok']:
        return out({'status': 'preflight_failed', **checked})
    idle = wait_for_idle(cfg, args.max_wait or cfg.restart['max_wait_seconds'])
    if not idle['ok']:
        return out({'status': 'not_idle', **idle})
    launched = launch_gateway(cfg, 'clanker-qa-restart')
    if await_health(cfg, launched):
        for finding in pending:
            set_status(finding, 'deployed', f"gateway {launched['pid']} started with this fix")
            save_finding(cfg, finding)
        state.pop('pending_setup_restart', None)
        save_state(cfg, state)
        return out({'status': 'restarted', 'old_pid': gateway['pid'], 'new_pid': launched['pid'],
                    'log': launched['log'], 'deployed': [f['id'] for f in pending], 'setup_activated': setup})
    if args.no_rollback:
        return out({'status': 'failed', 'log': launched['log'], 'gateway': gateway_state(cfg)})
    reverted = {}
    for finding in pending:
        restored, conflicts = revert_finding(cfg, finding['id'])
        set_status(finding, 'diagnosing', f"reverted after the gateway failed to start (log {launched['log']})")
        save_finding(cfg, finding)
        reverted[finding['id']] = {'restored': restored, 'conflicts': conflicts}
    if setup and state.get('config_backup'):
        write_file(cfg.lab_home / 'config.yaml', Path(state['config_backup']).read_bytes())
        state.pop('pending_setup_restart', None)
        save_state(cfg, state)
    relaunched = launch_gateway(cfg, 'clanker-qa-rollback')
    healthy = await_health(cfg, relaunched)
    out({'status': 'rolled_back' if healthy else 'failed', 'failed_log': launched['log'],
         'rollback_log': relaunched['log'], 'reverted': reverted, 'gateway': gateway_state(cfg)})


def summarize_run(cfg, run, settles):
    root = run['roots'][0]
    return {'id': run['id'], 'scenario': run['scenario'], 'variant': run['variant'], 'surface': run['surface'],
            'actor': run['actor'], 'secondary': run.get('secondary'), 'tester_messages': len(posts(run)),
            'sent_followups': run.get('sent_followups', []), 'followups': len(run.get('followups') or []),
            'gate': run.get('gate'), 'verify': run.get('verify'), 'last_wait': settles[-1] if settles else None,
            'permalink': permalink(cfg, root['channel'], root['ts'])}


def cmd_status(cfg, args):
    state = load_state(cfg)
    findings = all_findings(cfg)
    run = None
    if state.get('current_run'):
        with contextlib.suppress(QAError):
            run = load_run(cfg, state['current_run'])
    settles = read_jsonl(run_dir(cfg, run['id']) / 'settles.jsonl') if run else []
    waiter = read_json(cfg.state_dir / 'waiter.json', {})
    now = time.time()
    out({'phase': derive_phase(state, findings, run), 'stop_reason': state.get('stop_reason'),
         'current_run': summarize_run(cfg, run, settles) if run else None,
         'open_findings': [{k: f.get(k) for k in ('id', 'title', 'severity', 'status', 'attempts')}
                           for f in findings if f['status'] in OPEN_STATUSES],
         'pending_setup_restart': bool(state.get('pending_setup_restart')),
         'waiter_running': bool(waiter) and is_our_waiter(waiter), 'gateway': gateway_state(cfg),
         'budget': {'runs_today': runs_today(state, now), **cfg.budget},
         'campaign': state.get('campaign') or {'n': 1, 'index': 0}, 'skill': str(SKILL_FILE)})


def cmd_stop(cfg, args):
    state = load_state(cfg)
    state['stop_reason'] = args.reason
    save_state(cfg, state)
    out({'stopped': True, 'reason': args.reason, 'killed_waiter': kill_waiter(cfg)})


def cmd_resume(cfg, args):
    state = load_state(cfg)
    reason = state.pop('stop_reason', None)
    save_state(cfg, state)
    out({'resumed': True, 'previous_reason': reason})


# ---------------------------------------------------------------- cli

def parser():
    root = argparse.ArgumentParser(prog='clanker_qa.py', description=__doc__.split('\n\n')[0])
    commands = root.add_subparsers(dest='command', required=True)

    def command(name, handler, text):
        sub = commands.add_parser(name, help=text, description=text)
        sub.set_defaults(handler=handler)
        return sub

    command('doctor', cmd_doctor, 'Verify tokens, DMs, gateway allowlist, gateway health and Kernel CLI.')
    sub = command('setup-gateway', cmd_setup_gateway, 'Allowlist the testers in platforms.slack.extra.api_human_users.')
    sub.add_argument('--apply', action='store_true', help='Write the change (a backup is kept); restart afterwards.')
    command('scenarios', cmd_scenarios, 'List benchmark scenarios with coverage.')
    command('next', cmd_next, 'Suggest the next scenario, variant, testers and surface.')
    sub = command('start', cmd_start, 'Post the opening message of a new run.')
    sub.add_argument('--scenario', required=True, help="Scenario id from 'scenarios', or 'adhoc' with --text.")
    sub.add_argument('--variant', required=True, choices=VARIANTS)
    sub.add_argument('--actor', required=True, help='Primary tester.')
    sub.add_argument('--secondary', help='Second tester for shared-channel or cross-user runs.')
    sub.add_argument('--surface', required=True, choices=('dm', 'channel'))
    sub.add_argument('--text', help='Opening message as the tester writes it (defaults to the benchmark text).')
    sub.add_argument('--verify', metavar='FINDING', help='Mark this run as the verification of a deployed finding.')
    sub.add_argument('--force', action='store_true', help='Ignore budget, spacing and in-flight checks.')
    sub = command('send', cmd_send, 'Post a tester message in the run.')
    sub.add_argument('--run')
    sub.add_argument('--actor', help='Defaults to the primary tester.')
    sub.add_argument('--text', required=True)
    sub.add_argument('--top-level', choices=('dm', 'channel'), help='Start a new top-level message instead of replying.')
    sub.add_argument('--root', help='Reply under this root ts instead of the latest root.')
    sub.add_argument('--mention', action='store_true', help='Mention Clanker (channel threads).')
    sub.add_argument('--followup', type=int, help='Index of the benchmark follow-up this message covers.')
    sub.add_argument('--kind', default='followup', choices=('followup', 'answer', 'probe', 'interrupt'))
    sub.add_argument('--force', action='store_true')
    sub = command('edit', cmd_edit, "Edit one of the run's tester messages.")
    sub.add_argument('--run')
    sub.add_argument('--ts', required=True)
    sub.add_argument('--text', required=True)
    sub = command('gate', cmd_gate, 'Record or clear a pending human gate for the run.')
    sub.add_argument('--run')
    sub.add_argument('--what')
    sub.add_argument('--clear', action='store_true')
    sub = command('wait', cmd_wait, 'Wait until the turn settles (or --idle N), then print the wake line.')
    sub.add_argument('--run')
    sub.add_argument('--idle', type=int, metavar='SECONDS', help='No run: sleep, then wake with a heartbeat.')
    sub.add_argument('--after', help="Baseline: 'now' or a Slack ts. Waits for Clanker activity after it.")
    for name in ('quiet', 'timeout', 'first-reply', 'heartbeat'):
        sub.add_argument(f'--{name}', type=int, metavar='SECONDS')
    sub = command('transcript', cmd_transcript, 'Write transcript.md for the run and summarize what is new.')
    sub.add_argument('--run')
    sub = command('evidence', cmd_evidence, 'Collect Hermes trajectory, local logs, Kernel records and checks.')
    sub.add_argument('--run')
    sub.add_argument('--live-logs', action='store_true', help='Also capture supervisor logs of live browsers.')
    sub = command('finish', cmd_finish, 'Record the verdict and close the run.')
    sub.add_argument('--run')
    sub.add_argument('--verdict', required=True, choices=VERDICTS)
    sub.add_argument('--summary', required=True)
    sub.add_argument('--finding', action='append')
    sub = command('finding', cmd_finding, 'Manage findings.')
    sub.add_argument('action', choices=('add', 'update', 'list', 'show'))
    sub.add_argument('--id')
    sub.add_argument('--title')
    sub.add_argument('--severity', choices=SEVERITIES)
    sub.add_argument('--fingerprint')
    sub.add_argument('--summary')
    sub.add_argument('--root-cause')
    sub.add_argument('--run')
    sub.add_argument('--status', choices=FINDING_STATUSES)
    sub.add_argument('--note')
    sub.add_argument('--decision-doc')
    sub.add_argument('--tests', nargs='*')
    sub.add_argument('--search')
    sub = command('snapshot', cmd_snapshot, 'Record files before a fix edits or creates them.')
    sub.add_argument('--finding', required=True)
    sub.add_argument('paths', nargs='+')
    sub = command('diff', cmd_diff, 'Write fix.patch; with --hermes-patch also write patches/hermes/<name>.patch.')
    sub.add_argument('--finding', required=True)
    sub.add_argument('--hermes-patch', metavar='NAME')
    sub = command('mark-fixed', cmd_mark_fixed, 'Freeze the fix and queue it for restart.')
    sub.add_argument('--finding', required=True)
    sub.add_argument('--tests', nargs='*')
    sub.add_argument('--decision-doc')
    sub.add_argument('--note')
    sub = command('revert', cmd_revert, 'Restore the files a finding changed.')
    sub.add_argument('--finding', required=True)
    sub.add_argument('--note')
    sub = command('restart', cmd_restart, 'Preflight, wait for an idle gateway, replace it, roll back on failure.')
    sub.add_argument('--max-wait', type=int, metavar='SECONDS')
    sub.add_argument('--no-rollback', action='store_true')
    sub.add_argument('--force', action='store_true', help='Restart even with nothing pending.')
    command('status', cmd_status, 'Show the loop phase, current run, findings and gateway.')
    sub = command('stop', cmd_stop, 'Stop the loop and kill the waiter.')
    sub.add_argument('--reason', required=True)
    command('resume', cmd_resume, 'Clear a stop.')
    return root


def main(argv=None):
    os.umask(0o077)
    args = parser().parse_args(argv)
    if hasattr(args, 'first_reply'):
        pass
    cfg = load_config()
    cfg.state_dir.mkdir(parents=True, exist_ok=True)
    os.chmod(cfg.state_dir, 0o700)
    try:
        args.handler(cfg, args)
    except QAError as error:
        out({'ok': False, 'error': str(error), **error.detail})
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())

