class FakeSlack:
    """Just enough of the Slack Web API for one DM conversation."""

    def __init__(self, user):
        self.user, self.messages, self.clock = user, {}, 1000.0

    def _ts(self):
        self.clock += 1
        return f'{self.clock:.6f}'

    def chat_postMessage(self, channel, text, thread_ts=None, **_):
        message = {'ts': self._ts(), 'user': self.user, 'text': text}
        if thread_ts:
            message['thread_ts'] = thread_ts
        self.messages.setdefault(channel, []).append(message)
        return {'ok': True, 'ts': message['ts']}

    def conversations_replies(self, channel, ts, **_):
        return {'ok': True, 'messages': [m for m in self.messages.get(channel, [])
                                         if m['ts'] == ts or m.get('thread_ts') == ts]}

    def conversations_history(self, channel, oldest=None, **_):
        top = [m for m in self.messages.get(channel, []) if m.get('thread_ts') in (None, m['ts'])]
        return {'ok': True, 'messages': [m for m in reversed(top) if float(m['ts']) >= float(oldest or 0)]}

    def clanker_says(self, channel, text, thread_ts):
        self.messages[channel].append({'ts': self._ts(), 'user': 'U0C5Z1ZQHQX', 'text': text, 'thread_ts': thread_ts})


