def wait_args(**overrides):
    return Namespace(**{'run': None, 'idle': None, 'after': None, 'quiet': None, 'timeout': None,
                        'first_reply': None, 'heartbeat': None, **overrides})


def wake_payload(output):
    line = output.strip().splitlines()[-1]
    assert line.startswith(qa.WAKE + ' ')
    return json.loads(line[len(qa.WAKE) + 1:])


def test_a_run_goes_from_start_to_finish(cfg, capsys, live):
    rows = qa.parse_benchmark(TABLE)
    started = run_cmd(cfg, qa.cmd_start, capsys, scenario=rows[1]['id'], variant='verbatim', actor='tanishq',
                      secondary=None, surface='dm', text='open my instamart cart from earlier', verify=None, force=False)
    with pytest.raises(qa.QAError):
        qa.cmd_start(cfg, Namespace(scenario=rows[1]['id'], variant='verbatim', actor='tanishq', secondary=None,
                                    surface='dm', text=None, verify=None, force=False))
    live.clanker_says('D0C6EAXPKEE', 'Your cart has one pack of noodles.', started['posted'])
    qa.cmd_wait(cfg, wait_args())
    assert wake_payload(capsys.readouterr().out) == {
        'prompt': '/clanker-qa', 'skill': str(qa.SKILL_FILE), 'event': 'settled', 'run': started['run']}
    transcript = run_cmd(cfg, qa.cmd_transcript, capsys, run=None)
    assert transcript['clanker_since_last_tester_message'] == 1 and transcript['unsent_followups'] == [0, 1]
    assert 'one pack of noodles' in Path(transcript['transcript']).read_text()
    sent = run_cmd(cfg, qa.cmd_send, capsys, run=None, actor=None, text='make that two packs', top_level=None,
                   root=None, mention=False, followup=0, kind='followup', force=False)
    assert live.messages['D0C6EAXPKEE'][-1] == {'ts': sent['posted'], 'user': 'U0C688SF7DZ',
                                                'text': 'make that two packs', 'thread_ts': started['posted']}
    finished = run_cmd(cfg, qa.cmd_finish, capsys, run=None, verdict='pass', summary='Cart opened.', finding=None)
    assert finished['campaign'] == {'n': 1, 'index': 0}
    status = run_cmd(cfg, qa.cmd_status, capsys)
    assert status['phase'] == 'idle' and status['current_run'] is None and status['budget']['runs_today'] == 1


